## Fold the Nebraska House county results 1990-2006 (elect_he_cty_ne_<year>.rds; 02x_house_ne_1990_1994.R, 02x_house_ne_1996_1998.R, 02x_house_ne_2000_2006.R, 02x_house_ne_2004.R; Secretary of State canvass books)
## into the panel. Nebraska had House rows only from 2008. Gate: none before 2008; positive REP medians (Democrats can be absent in unopposed years, so only Republican and total are gated); everything else unchanged. Backup: backup_ne/. 2026-09-21.
source(file.path("R", "00_setup.R"))
panel <- readRDS(file.path(OUTPUT_DIR, "elect_cty_final.rds"))
bk <- "/tmp/claude-1000/-home-paul-Stats-substack-projects-immigration/831fbe11-26b0-4ba2-9f03-261a9fbdf053/scratchpad/backup_ne"; dir.create(bk, showWarnings = FALSE)
if (!file.exists(file.path(bk, "elect_cty_final_before_ne.rds"))) saveRDS(panel, file.path(bk, "elect_cty_final_before_ne.rds"))
stopifnot(all(panel$year[panel$sample == "HE" & panel$cty_fips %/% 1000 == 31] >= 2008))
yrs <- seq(1990, 2006, 2)
new <- purrr::map_dfr(sprintf("elect_he_cty_ne_%d.rds", yrs), function(f) readRDS(file.path(OUTPUT_DIR, f))) %>% transmute(year, cty_fips, sample, demovote, repuvote, totalvote, state = NA_character_)
stopifnot(!anyDuplicated(new[, c("year", "cty_fips", "sample")]), !anyNA(new[, c("demovote", "repuvote", "totalvote")]), all(new$totalvote > 0), all(new$cty_fips %/% 1000 == 31), nrow(new) == 9 * 93)
sh <- new %>% group_by(year) %>% summarise(med_dem = median(demovote), med_rep = median(repuvote), .groups = "drop"); print(as.data.frame(sh)); stopifnot(all(sh$med_rep > 0.4), sum(sh$med_dem > 0.05) >= 6)
p2 <- bind_rows(panel, new[, names(panel)]); stopifnot(anyDuplicated(p2[, c("year", "cty_fips", "sample")]) == 0)
stopifnot(isTRUE(all.equal(panel %>% arrange(year, cty_fips, sample), p2 %>% filter(!(sample == "HE" & cty_fips %/% 1000 == 31 & year <= 2006)) %>% arrange(year, cty_fips, sample), check.attributes = FALSE)))
saveRDS(p2, file.path(OUTPUT_DIR, "elect_cty_final.rds")); message("added ", nrow(new), " Nebraska House county-years; panel rows ", nrow(panel), " -> ", nrow(p2))
